import React from "react";
import "./dashboard.css";


/**
 * Universal profile card.
 * Accepts admin / ngo / user data shape.
 * Example fields: { id, name, email, role, totalEvents, points, phone }
 */
export default function UserProfileCard({ data }) {
  if (!data) {
    return (
      <div className="card profile-placeholder">
        <div className="loading">No profile loaded</div>
      </div>
    );
  }

  const role = (data.role || data.type || "User").toString();

  return (
    <div className="card profile-card">
      <div className="profile-top">
        <div className="avatar">{(data.name || data.email || "U").charAt(0).toUpperCase()}</div>
        <div className="profile-meta">
          <div className="name">{data.name || "No Name"}</div>
          <div className="muted small">{data.email}</div>
        </div>
        <div className={`role-badge ${role.toLowerCase()}`}>{role}</div>
      </div>

      <div className="profile-body">
        <div className="profile-stat">
          <div className="stat-num">{data.points ?? 0}</div>
          <div className="stat-label">Total Points</div>
        </div>

        <div className="profile-list">
          {data.totalEvents !== undefined && <div><strong>Events:</strong> {data.totalEvents}</div>}
          {data.phone && <div><strong>Phone:</strong> {data.phone}</div>}
          {data.registrationId && <div><strong>Reg ID:</strong> {data.registrationId}</div>}
          {data.address && <div className="muted small">{data.address}</div>}
        </div>
      </div>
    </div>
  );
}
